with StoreTotals as (select store_id, count(distinct quantity) as unique_stores, round(avg(quantity), 2) as avg_quantity from inventory where quantity < 173 group by store_id) select stores.id, stores.city, stores.opened_date, StoreTotals.unique_stores, StoreTotals.avg_quantity from stores left join StoreTotals on stores.id = StoreTotals.store_id where StoreTotals.avg_quantity > 75 order by id desc;
